// Builds docs/max-preview.html: a single self-contained page (inline CSS and
// JS, no external requests) that shows Max in demo mode, cycling every state.
// It is generated from docs/max-widget.js and docs/max-widget.css; do not edit
// the HTML by hand.
//
//   node scripts/build-max-preview.mjs          write docs/max-preview.html
//   node scripts/build-max-preview.mjs --check  exit 1 if it is out of date
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const docs = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'docs');
const css = fs.readFileSync(path.join(docs, 'max-widget.css'), 'utf8');
const js = fs.readFileSync(path.join(docs, 'max-widget.js'), 'utf8');
if (/<\/(script|style)/i.test(css + js)) throw new Error('widget source contains a closing script/style tag');

const html = `<!DOCTYPE html>
<!-- GENERATED by scripts/build-max-preview.mjs from max-widget.js and max-widget.css. Do not edit by hand. -->
<html lang="en" data-theme="light">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>RegRadar: Max preview</title>
<meta name="description" content="Preview of Max, RegRadar's assistant, cycling through every animation state. Prototype.">
<style>
:root{--bg:#F5F6F8;--surface:#FFFFFF;--border:#E3E6EC;--text:#16202C;--text-2:#455163;--accent:#0A4FD6;--on-accent:#FFFFFF}
html[data-theme="dark"]{--bg:#0E1117;--surface:#151A21;--border:#232B36;--text:#E6EDF3;--text-2:#AAB4C6;--accent:#6D9BFF;--on-accent:#06101F}
*{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--text);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Helvetica Neue",Helvetica,Arial,sans-serif;min-height:100vh}
main{max-width:720px;margin:0 auto;padding:40px 20px 160px}
h1{font-size:26px;letter-spacing:-.02em}
p{color:var(--text-2);margin-top:10px;max-width:62ch}
.card{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:16px 18px;margin-top:20px}
button.t{margin-top:18px;min-height:44px;padding:0 16px;border-radius:10px;border:1px solid var(--accent);background:var(--accent);color:var(--on-accent);font:inherit;font-weight:600;cursor:pointer}
button.t:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
footer{text-align:center;font-size:12.5px;color:var(--text-2);padding:20px}
</style>
<style id="max-widget-css">
${css}</style>
</head>
<body>
<main>
  <h1>Max preview</h1>
  <p>Max cycles through his states every few seconds at the bottom right: walking, arriving in the bubble, idle, hover tooltip, thinking, found a source, not sure. Click him to open the chat panel shell. Chat is not built yet.</p>
  <button class="t" type="button" id="theme">Switch light / dark</button>
  <div class="card"><p>Sample page content so the frosted glass has something to blur. RegRadar is a prototype; nothing here is legal advice.</p></div>
  <div class="card"><p>This file is generated from <code>max-widget.js</code> and <code>max-widget.css</code> by <code>scripts/build-max-preview.mjs</code>.</p></div>
</main>
<footer><p>RegRadar prototype. Not legal advice.</p></footer>
<script>
document.getElementById('theme').addEventListener('click',function(){var h=document.documentElement;h.setAttribute('data-theme',h.getAttribute('data-theme')==='dark'?'light':'dark')});
window.MAX_PREVIEW = true;
</script>
<script>
${js}</script>
</body>
</html>
`;

const out = path.join(docs, 'max-preview.html');
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (cur !== html) { console.error('docs/max-preview.html is out of date: run node scripts/build-max-preview.mjs'); process.exit(1); }
  console.log('docs/max-preview.html is up to date.');
} else {
  fs.writeFileSync(out, html);
  console.log('Wrote docs/max-preview.html');
}
